// AUTO-GENERATED by server-split — do not edit by hand.
import db, { logAction, createNotification } from "../config/postgres";
import { kioskLimiter, pairPhoneLimiter, enrollLimiter } from "../middleware/auth";
import crypto from "crypto";
import express from "express";
import {
  verifyAuthenticationResponse,
  verifyRegistrationResponse,
} from "@simplewebauthn/server";
import {
  ChallengeStore,
  expectedOriginFor as resolveOrigin,
  kioskRpId as resolveRpId,
} from "../lib/webauthn-challenges";

export function registerAttendance(app: express.Express) {

    // Attendance

  app.get("/api/attendance", async (req, res) => {
    const { month, year } = req.query;
    const data = await db.prepare(`
      SELECT a.*, e.name as employee_name 
      FROM attendance a
      JOIN employees e ON a.employee_id = e.id
      WHERE a.month = ? AND a.year = ?
    `).all(month, year);
    res.json(data);
  });

  app.post("/api/attendance", async (req, res) => {
    const { employee_id, month, year, absence_days, overtime_hours } = req.body;
    await db.prepare(`
      INSERT INTO attendance (employee_id, month, year, absence_days, overtime_hours)
      VALUES (?, ?, ?, ?, ?)
    `).run(employee_id, month, year, absence_days, overtime_hours);
    res.json({ success: true });
  });

    // Haversine distance in meters

  function haversineMeters(lat1: number, lng1: number, lat2: number, lng2: number): number {
    const R = 6371000;
    const toRad = (d: number) => (d * Math.PI) / 180;
    const dLat = toRad(lat2 - lat1);
    const dLng = toRad(lng2 - lng1);
    const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
    return 2 * R * Math.asin(Math.sqrt(a));
  }

    // ---- Attendance Devices ----

  app.get("/api/attendance/devices", async (req, res) => {
    try {
      const rows = await db.prepare(`
        SELECT d.*, b.name as branch_name FROM attendance_devices d
        LEFT JOIN branches b ON b.id = d.branch_id ORDER BY d.id DESC
      `).all();
      res.json(rows);
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

  app.post("/api/attendance/devices", async (req, res) => {
    try {
      const { branch_id, device_name, device_token } = req.body;
      if (!branch_id) return res.status(400).json({ error: "branch_id مطلوب" });
      const branch = await db.prepare("SELECT * FROM branches WHERE id = ?").get(branch_id) as any;
      if (!branch) return res.status(404).json({ error: "الفرع غير موجود" });
      if (branch.latitude == null || branch.longitude == null) {
        return res.status(400).json({ error: "حدّد إحداثيات الفرع ونطاقه من شاشة الفروع قبل ربط الهاتف" });
      }
      const token = device_token || `DEV-${Date.now()}-${crypto.randomBytes(16).toString("hex")}`;
      const pin = String(crypto.randomInt(0, 1000000)).padStart(6, "0");
      const result = await db.prepare(
        "INSERT INTO attendance_devices (branch_id, device_name, device_token, pairing_pin, phone_bound) VALUES (?, ?, ?, ?, 0)"
      ).run(branch_id, device_name || "هاتف الفرع", token, pin);
      await logAction("create", "attendance_device", Number(result.lastInsertRowid), `Phone pairing created for branch ${branch_id}`);
      res.json({ id: result.lastInsertRowid, device_token: token, pairing_pin: pin, success: true });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

  app.post("/api/attendance/devices/:id/reset-pair", async (req, res) => {
    try {
      const pin = String(crypto.randomInt(0, 1000000)).padStart(6, "0");
      await db.prepare("UPDATE attendance_devices SET phone_bound = 0, bound_fingerprint = NULL, bound_at = NULL, pairing_pin = ? WHERE id = ?")
        .run(pin, req.params.id);
      await logAction("update", "attendance_device", Number(req.params.id), "إعادة تفعيل هاتف الفرع (إلغاء الربط السابق)");
      res.json({ success: true, pairing_pin: pin });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

  async function requirePairedPhoneAtBranch(device: any, latitude: any, longitude: any, fingerprint?: string) {
    if (!device.phone_bound) {
      return { ok: false, status: 403, error: "هذا الهاتف غير مفعّل. فعّله أول مرة داخل موقع الفرع برقم التفعيل." };
    }
    if (!fingerprint || !String(fingerprint).trim()) {
      await db.prepare("INSERT INTO kiosk_security_logs (device_id, reason, details) VALUES (?, ?, ?)")
        .run(device.id, "missing_fingerprint", "طلب تسجيل بدون device_fingerprint");
      return { ok: false, status: 400, error: "معرّف الهاتف (device_fingerprint) مطلوب — لا يمكن التسجيل بدونه" };
    }
    if (device.bound_fingerprint && device.bound_fingerprint !== fingerprint) {
      await db.prepare("INSERT INTO kiosk_security_logs (device_id, reason, details) VALUES (?, ?, ?)")
        .run(device.id, "device_mismatch", "هاتف غير المرتبط بالفرع");
      return { ok: false, status: 403, error: "هذا الرابط مربوط بهاتف فرع آخر فقط" };
    }
    if (latitude == null || longitude == null) {
      return { ok: false, status: 400, error: "الموقع الجغرافي إلزامي — لن يتم التسجيل بدون GPS" };
    }
    const branch = await db.prepare("SELECT * FROM branches WHERE id = ?").get(device.branch_id) as any;
    if (!branch || branch.latitude == null || branch.longitude == null) {
      return { ok: false, status: 400, error: "الفرع بلا إحداثيات" };
    }
    const dist = haversineMeters(Number(branch.latitude), Number(branch.longitude), Number(latitude), Number(longitude));
    const radius = Number(branch.geofence_radius_m) || 200;
    if (dist > radius) {
      await db.prepare("INSERT INTO kiosk_security_logs (device_id, reason, details) VALUES (?, ?, ?)")
        .run(device.id, "geofence", `خارج النطاق ${Math.round(dist)}م`);
      return { ok: false, status: 403, error: `الهاتف خارج موقع الفرع (${Math.round(dist)}م) — يُمنع التسجيل`, distance_m: Math.round(dist), radius_m: radius };
    }
    return { ok: true, branch, distance_m: Math.round(dist), radius_m: radius };
  }

  app.post("/api/attendance/pair-phone", pairPhoneLimiter, kioskLimiter, async (req, res) => {
    try {
      const { device_token, pairing_pin, latitude, longitude, device_fingerprint } = req.body;
      const device = await db.prepare("SELECT * FROM attendance_devices WHERE device_token = ?").get(device_token) as any;
      if (!device) return res.status(404).json({ error: "رابط الفرع غير صالح", allowed: false });
      if (device.phone_bound) {
        if (device.bound_fingerprint === device_fingerprint) {
          return res.json({ success: true, already: true, message: "الهاتف مفعّل مسبقاً" });
        }
        return res.status(403).json({ error: "تم ربط هاتف آخر بهذا الفرع. اطلب إعادة التفعيل من الإدارة.", allowed: false });
      }
      if (!pairing_pin || String(pairing_pin) !== String(device.pairing_pin)) {
        await db.prepare("INSERT INTO kiosk_security_logs (device_id, reason, details) VALUES (?, ?, ?)")
          .run(device.id, "bad_pin", "رمز تفعيل خاطئ");
        return res.status(403).json({ error: "رمز التفعيل غير صحيح", allowed: false });
      }
      if (latitude == null || longitude == null) {
        return res.status(400).json({ error: "فعّل GPS. لا يمكن ربط الهاتف إلا داخل موقع الفرع.", allowed: false });
      }
      const branch = await db.prepare("SELECT * FROM branches WHERE id = ?").get(device.branch_id) as any;
      if (!branch || branch.latitude == null || branch.longitude == null) {
        return res.status(400).json({ error: "الفرع لا يملك إحداثيات", allowed: false });
      }
      const dist = haversineMeters(Number(branch.latitude), Number(branch.longitude), Number(latitude), Number(longitude));
      const radius = Number(branch.geofence_radius_m) || 200;
      if (dist > radius) {
        await db.prepare("INSERT INTO kiosk_security_logs (device_id, reason, details) VALUES (?, ?, ?)")
          .run(device.id, "pair_outside", `محاولة تفعيل خارج الفرع ${Math.round(dist)}م`);
        return res.status(403).json({
          error: `لا يمكن تفعيل الهاتف إلا داخل نطاق الفرع. أنت على بعد ${Math.round(dist)}م (المسموح ${radius}م)`,
          allowed: false, distance_m: Math.round(dist), radius_m: radius
        });
      }
      if (!device_fingerprint) return res.status(400).json({ error: "تعذر توليد معرف الهاتف" });
      await db.prepare(`UPDATE attendance_devices SET phone_bound = 1, bound_fingerprint = ?, bound_at = ?, last_latitude = ?, last_longitude = ?, last_verified_at = ? WHERE id = ?`)
        .run(device_fingerprint, new Date().toISOString(), latitude, longitude, new Date().toISOString(), device.id);
      await logAction("update", "attendance_device", device.id, `Phone paired at branch ${branch.name}`);
      res.json({ success: true, allowed: true, branch_name: branch.name, distance_m: Math.round(dist), message: `تم ربط هاتف فرع ${branch.name}` });
    } catch (e) { res.status(500).json({ error: (e as Error).message, allowed: false }); }
  });

  // Suspend or resume a kiosk without deleting it. Suspended devices stay
// configured (and their biometric credentials intact) but are refused by
// /api/kiosk/:token and by the WebAuthn ceremony.
app.patch("/api/attendance/devices/:id", async (req, res) => {
    try {
      const { id } = req.params;
      const { is_active } = req.body || {};
      if (is_active === undefined) {
        return res.status(400).json({ error: "is_active مطلوب (0 أو 1)" });
      }
      const active = is_active ? 1 : 0;
      const result = await db.prepare("UPDATE attendance_devices SET is_active = ? WHERE id = ?").run(active, id);
      if (!result.changes) return res.status(404).json({ error: "الجهاز غير موجود" });
      await logAction("update", "attendance_device", Number(id), active ? "Device resumed" : "Device suspended");
      res.json({ success: true, id: Number(id), is_active: active });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

  app.delete("/api/attendance/devices/:id", async (req, res) => {
    try {
      await db.prepare("DELETE FROM attendance_devices WHERE id = ?").run(req.params.id);
      res.json({ success: true });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

    // ---- Geo validation: device must be within branch geofence ----

  app.post("/api/attendance/geo-validate", async (req, res) => {
    try {
      const { device_token, latitude, longitude, device_fingerprint } = req.body;
      const device = await db.prepare("SELECT * FROM attendance_devices WHERE device_token = ?").get(device_token) as any;
      if (!device) return res.status(404).json({ error: "الجهاز غير مسجل", allowed: false });
      const chk = await requirePairedPhoneAtBranch(device, latitude, longitude, device_fingerprint);
      if (!chk.ok) return res.status(chk.status || 403).json({ error: chk.error, allowed: false, distance_m: chk.distance_m, radius_m: chk.radius_m });
      await db.prepare("UPDATE attendance_devices SET last_latitude = ?, last_longitude = ?, last_verified_at = ? WHERE id = ?")
        .run(latitude, longitude, new Date().toISOString(), device.id);
      res.json({ allowed: true, distance_m: chk.distance_m, radius_m: chk.radius_m, branch_id: device.branch_id, branch_name: chk.branch.name, paired: true });
    } catch (e) { res.status(500).json({ error: (e as Error).message, allowed: false }); }
  });

  app.get("/api/attendance/live", async (_req, res) => {
    try {
      const today = new Date().toISOString().slice(0, 10);
      const rows = await db.prepare(`
        SELECT l.*, e.name as employee_name, b.name as branch_name
        FROM attendance_logs l
        LEFT JOIN employees e ON e.id = l.employee_id
        LEFT JOIN branches b ON b.id = l.branch_id
        WHERE l.check_in_time::date = ?
        ORDER BY l.check_in_time DESC
      `).all(today);
      const geo_fails = await db.prepare(`
        SELECT * FROM kiosk_security_logs WHERE created_at >= CURRENT_TIMESTAMP - INTERVAL '1 day' ORDER BY id DESC LIMIT 50
      `).all();
      res.json({ today: rows, geo_fails });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

  app.get("/api/attendance/branch-month-report", async (req, res) => {
    try {
      const month = Number(req.query.month) || new Date().getMonth() + 1;
      const year = Number(req.query.year) || new Date().getFullYear();
      const prefix = `${year}-${String(month).padStart(2, "0")}`;
      const rows = await db.prepare(`
        SELECT e.id as employee_id, e.name as employee_name, b.name as branch_name, e.branch_id,
          COUNT(DISTINCT l.check_in_time::date) as present_days,
          SUM(CASE WHEN l.status = 'late' THEN 1 ELSE 0 END) as late_days,
          a.absence_days, a.overtime_hours
        FROM employees e
        LEFT JOIN branches b ON b.id = e.branch_id
        LEFT JOIN attendance_logs l ON l.employee_id = e.id AND substr(CAST(l.check_in_time AS TEXT), 1, 7) = ?
        LEFT JOIN attendance a ON a.employee_id = e.id AND a.month = ? AND a.year = ?
        GROUP BY e.id, e.name, e.branch_id, b.name, a.absence_days, a.overtime_hours
        ORDER BY b.name, e.name
      `).all(prefix, month, year);
      res.json({ month, year, rows });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

    // ---- Check-in ----

  app.post("/api/attendance/check-in", kioskLimiter, async (req, res) => {
    try {
      const { device_token, employee_id, method, latitude, longitude, device_fingerprint } = req.body;
      const device = await db.prepare("SELECT * FROM attendance_devices WHERE device_token = ?").get(device_token) as any;
      if (!device) return res.status(404).json({ error: "الجهاز غير مسجل" });
      const gate = await requirePairedPhoneAtBranch(device, latitude, longitude, device_fingerprint);
      if (!gate.ok) return res.status(gate.status || 403).json({ error: gate.error, allowed: false });
      const branch = gate.branch;
      const emp = await db.prepare("SELECT * FROM employees WHERE id = ?").get(employee_id) as any;
      if (!emp) return res.status(404).json({ error: "الموظف غير موجود" });
      if (emp.branch_id && Number(emp.branch_id) !== Number(device.branch_id)) {
        return res.status(403).json({ error: "الموظف غير تابع لهذا الفرع — يُمنع التسجيل على هاتف فرع آخر" });
      }
      const today = new Date().toISOString().slice(0, 10);
      const existing = await db.prepare(`
        SELECT * FROM attendance_logs WHERE employee_id = ? AND check_in_time::date = ?
      `).get(employee_id, today) as any;
      if (existing && existing.check_out_time) {
        return res.status(400).json({ error: "تم تسجيل الحضور والانصراف مسبقاً اليوم" });
      }
      const now = new Date().toISOString();
      let logId = existing ? existing.id : null;
      if (existing) {
        await db.prepare("UPDATE attendance_logs SET check_in_time = ?, branch_id = ?, device_id = ?, method = ?, check_in_lat = ?, check_in_lng = ? WHERE id = ?")
          .run(now, device.branch_id, device.id, method || 'manual', latitude || null, longitude || null, existing.id);
      } else {
        const start = branch?.work_start_time || '08:00';
        const checkInHour = new Date().toTimeString().slice(0, 5);
        const status = checkInHour > start ? 'late' : 'present';
        const r = await db.prepare(`
          INSERT INTO attendance_logs (employee_id, branch_id, device_id, check_in_time, check_in_lat, check_in_lng, method, status)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        `).run(employee_id, device.branch_id, device.id, now, latitude || null, longitude || null, method || 'manual', status);
        logId = Number(r.lastInsertRowid);
      }
      await createNotification('تسجيل حضور', `تم تسجيل حضور ${emp.name} عبر ${method || 'الجه'}` , 'success');
      res.json({ id: logId, success: true, message: 'تم تسجيل الحضور' });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

    // ---- Check-out ----

  app.post("/api/attendance/check-out", kioskLimiter, async (req, res) => {
    try {
      const { device_token, employee_id, latitude, longitude, device_fingerprint } = req.body;
      const device = await db.prepare("SELECT * FROM attendance_devices WHERE device_token = ?").get(device_token) as any;
      if (!device) return res.status(404).json({ error: "الجهاز غير مسجل" });
      const gate = await requirePairedPhoneAtBranch(device, latitude, longitude, device_fingerprint);
      if (!gate.ok) return res.status(gate.status || 403).json({ error: gate.error, allowed: false });
      const today = new Date().toISOString().slice(0, 10);
      const existing = await db.prepare(`
        SELECT * FROM attendance_logs WHERE employee_id = ? AND check_in_time::date = ? AND check_out_time IS NULL
      `).get(employee_id, today) as any;
      if (!existing) return res.status(400).json({ error: "لا يوجد تسجيل دخول مفتوح اليوم" });
      const now = new Date().toISOString();
      await db.prepare("UPDATE attendance_logs SET check_out_time = ?, check_out_lat = ?, check_out_lng = ? WHERE id = ?")
        .run(now, latitude || null, longitude || null, existing.id);
      const emp = await db.prepare("SELECT name FROM employees WHERE id = ?").get(employee_id) as any;
      await createNotification('تسجيل انصراف', `تم تسجيل انصراف ${emp?.name || ''}` , 'info');
      res.json({ success: true, message: 'تم تسجيل الانصراف' });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

    // ---- Attendance logs ----

  app.get("/api/attendance/logs", async (req, res) => {
    try {
      const rows = await db.prepare(`
        SELECT l.*, e.name as employee_name, b.name as branch_name
        FROM attendance_logs l
        LEFT JOIN employees e ON e.id = l.employee_id
        LEFT JOIN branches b ON b.id = l.branch_id
        ORDER BY l.check_in_time DESC
      `).all();
      res.json(rows);
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

    // ---- Biometrics ----
    // Enrollment is gated by the central auth gate + BIOMETRIC_ENROLL rule (admin, hr_manager,
    // branch_manager); the limiter is attached here because the policy table is method/path only.

  app.post("/api/biometric/register", enrollLimiter, async (req, res) => {
    try {
      const { employee_id, face_template } = req.body;
      if (!employee_id) return res.status(400).json({ error: "employee_id مطلوب" });
      await db.prepare("UPDATE employees SET face_template = ? WHERE id = ?").run(face_template || null, employee_id);
      await logAction("update", "employee", employee_id, "Biometric face template registered");
      res.json({ success: true });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

// Single-use, short-lived WebAuthn challenges, keyed by flow. Lives in
  // server/lib so the anti-replay lifecycle is unit tested.
  const challengeStore = new ChallengeStore();
  const consumeChallenge = (key: string) => challengeStore.consume(key);

  // Periodically drop expired ceremonies so a long-lived kiosk process does not
  // accumulate abandoned challenges.
  const challengeSweep = setInterval(() => challengeStore.prune(), 60_000);
  challengeSweep.unref?.();

  // The relying party origin must match where the browser actually ran the
  // ceremony. Configurable for deployments behind a proxy or custom hostname.
  const expectedOriginFor = (req: express.Request): string => resolveOrigin(req);

  const b64url = (buf: Uint8Array | Buffer) => Buffer.from(buf).toString("base64url");

  const kioskRpId = () => resolveRpId();

  app.get("/api/kiosk/:token", kioskLimiter, async (req, res) => {
    try {
      const device = await db.prepare(`
        SELECT d.*, b.name as branch_name FROM attendance_devices d
        LEFT JOIN branches b ON b.id = d.branch_id WHERE d.device_token = ?
      `).get(req.params.token) as any;
      if (!device || device.is_active === 0) return res.status(404).json({ error: "رابط الفرع غير صالح" });
      res.json({
        device_name: device.device_name,
        branch_id: device.branch_id,
        branch_name: device.branch_name,
        // Derived from is_active, the column that actually exists on this table.
        status: device.is_active === 0 ? "inactive" : "active",
        is_active: device.is_active === 1,
        phone_bound: !!device.phone_bound,
        needs_pairing: !device.phone_bound,
      });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

  app.post("/api/webauthn/register/options", enrollLimiter, async (req, res) => {
    try {
      const { employee_id } = req.body;
      const emp = await db.prepare("SELECT * FROM employees WHERE id = ?").get(employee_id) as any;
      if (!emp) return res.status(404).json({ error: "الموظف غير موجود" });
      const challenge = b64url(crypto.randomBytes(32));
      challengeStore.issue(`register:${employee_id}`, challenge, Number(employee_id));
      const userId = b64url(Buffer.from(`emp-${employee_id}`));
      res.json({
        challenge,
        rpId: kioskRpId(),
        rpName: "نظام الرواتب - حضور الفرع",
        userId,
        userName: emp.name,
        userDisplayName: emp.name,
      });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

  app.post("/api/webauthn/register", enrollLimiter, async (req, res) => {
    try {
      const { employee_id, credentialId, method, attestationObject, clientDataJSON } = req.body;
      if (!employee_id || !credentialId || !attestationObject || !clientDataJSON) {
        return res.status(400).json({ error: "بيانات البصمة ناقصة" });
      }
      const pendingChallenge = consumeChallenge(`register:${employee_id}`);
      if (!pendingChallenge) {
        return res.status(400).json({ error: "انتهت صلاحية جلسة التسجيل — أعد المحاولة" });
      }

      const expectedRPID = kioskRpId();
      const expectedOrigin = expectedOriginFor(req);

      const verification = await verifyRegistrationResponse({
        response: {
          id: credentialId,
          rawId: credentialId,
          response: {
            attestationObject,
            clientDataJSON,
          },
          clientExtensionResults: {},
          type: "public-key",
        },
        expectedChallenge: pendingChallenge,
        expectedOrigin,
        expectedRPID,
        requireUserVerification: false,
      });

      if (verification.verified) {
        await db.prepare("DELETE FROM employee_webauthn_credentials WHERE employee_id = ?").run(employee_id);
        await db.prepare(`
          INSERT INTO employee_webauthn_credentials (employee_id, credential_id, public_key, counter, transports, method)
          VALUES (?, ?, ?, ?, ?, ?)
        `).run(
          employee_id,
          credentialId,
          b64url(verification.registrationInfo.credential.publicKey),
          verification.registrationInfo.credential.counter,
          (req.body.transports as string[] | undefined)?.join(",") || "internal",
          method || "face",
        );
        await logAction("update", "employee", employee_id, "WebAuthn biometric enrolled");
        return res.json({ success: true });
      } else {
        return res.status(400).json({ error: "فشل تسجيل البصمة" });
      }
    } catch (e) {
      console.error("WebAuthn registration error:", e);
      return res.status(500).json({ error: "خطأ في تسجيل البصمة" });
    }
  });

  app.post("/api/webauthn/login/options", kioskLimiter, async (req, res) => {
    try {
      const { device_token } = req.body;
      const device = await db.prepare("SELECT * FROM attendance_devices WHERE device_token = ?").get(device_token) as any;
      if (!device) return res.status(404).json({ error: "الجهاز غير مسجل" });
      if (device.is_active === 0) return res.status(403).json({ error: "الجهاز موقوف" });
      // Keyed by device so the verification step can look the challenge up.
      const challenge = b64url(crypto.randomBytes(32));
      challengeStore.issue(`login:${device_token}`, challenge);
      res.json({ challenge, rpId: kioskRpId() });
    } catch (e) { res.status(500).json({ error: (e as Error).message }); }
  });

  app.post("/api/webauthn/login", kioskLimiter, async (req, res) => {
    try {
      const { device_token, credentialId, clientDataJSON, authenticatorData, signature, userHandle } = req.body;
      if (!device_token || !credentialId || !clientDataJSON || !authenticatorData || !signature) {
        return res.status(400).json({ error: "لم تُستلم البصمة" });
      }

      // The ceremony must have been started by a registered, active kiosk.
      const device = await db.prepare("SELECT * FROM attendance_devices WHERE device_token = ?").get(device_token) as any;
      if (!device) return res.status(404).json({ error: "الجهاز غير مسجل" });
      if (device.is_active === 0) return res.status(403).json({ error: "الجهاز موقوف" });

      // Consume the challenge issued by /login/options. Consuming it here makes
      // it single-use, so a captured assertion cannot be replayed.
      const expectedChallenge = consumeChallenge(`login:${device_token}`);
      if (!expectedChallenge) {
        return res.status(400).json({ error: "انتهت صلاحية الجلسة — أعد المحاولة" });
      }

      // Find the credential
      const credential = await db.prepare(`
        SELECT c.*, e.name, e.position, e.branch_id, e.id as employee_id
        FROM employee_webauthn_credentials c
        JOIN employees e ON e.id = c.employee_id
        WHERE c.credential_id = ?
      `).get(credentialId) as any;

      if (!credential) {
        return res.status(404).json({ error: "البصمة غير مسجّلة. سجّل الموظف أولاً من شاشة الكiosk" });
      }

      const expectedRPID = kioskRpId();
      const expectedOrigin = expectedOriginFor(req);

      const verification = await verifyAuthenticationResponse({
        response: {
          id: credentialId,
          rawId: credentialId,
          response: {
            clientDataJSON,
            authenticatorData,
            signature,
            userHandle: userHandle || undefined,
          },
          clientExtensionResults: {},
          type: "public-key",
        },
        expectedChallenge,
        expectedOrigin,
        expectedRPID,
        credential: {
          id: credentialId,
          publicKey: Buffer.from(credential.public_key, "base64url"),
          counter: credential.counter,
          transports: credential.transports ? credential.transports.split(",") : [],
        },
      });

      if (verification.verified) {
        await db.prepare("UPDATE employee_webauthn_credentials SET counter = ? WHERE credential_id = ?")
          .run(verification.authenticationInfo.newCounter, credentialId);

        return res.json({
          success: true,
          employee: {
            id: credential.employee_id,
            name: credential.name,
            position: credential.position,
            branch_id: credential.branch_id,
          },
        });
      } else {
        return res.status(401).json({ error: "فشل التحقق من البصمة" });
      }
    } catch (e) {
      console.error("WebAuthn login error:", e);
      return res.status(500).json({ error: "خطأ في التحقق من البصمة" });
    }
  });

}
